README:
# Checkout pricing

Active members receive ten percent off; expired members pay the standard price.

Plain JavaScript on Node.js, with no dependencies or compilation step.

Optional ordinary test captures: test-results/test.stdout, test-results/test.stderr, test-results/test.exit. These are raw execution output, not delivery receipts.

Tests:
checkout/tests/architecture.test.mjs
import test from 'node:test'
import assert from 'node:assert/strict'
import { readFileSync } from 'node:fs'

test('pricing dependencies point inward', () => {
  const read = path => readFileSync(new URL(path, import.meta.url), 'utf8')
  const imports = text => [...text.matchAll(/from ['"]([^'"]+)['"]/g)].map(match => match[1])
  assert.doesNotMatch(read('../src/domain/price.mjs'), /\b(?:import|require)\b/)
  assert.deepEqual(imports(read('../src/application/quote.mjs')), ['../domain/price.mjs'])
  assert.deepEqual(imports(read('../src/adapters/quote-json.mjs')), ['../application/quote.mjs'])
})
checkout/tests/pricing.test.mjs
import test from 'node:test'
import assert from 'node:assert/strict'
import { quote } from '../src/application/quote.mjs'
import { quoteJson } from '../src/adapters/quote-json.mjs'

test('active members receive ten percent off', () => {
  assert.equal(quote(100, true), 90)
})
test('expired members pay standard price', () => {
  assert.equal(quote(100, false), 100)
})
test('empty baskets remain free', () => {
  assert.equal(quote(0, true), 0)
})
test('the JSON boundary returns the quoted total', () => {
  assert.deepEqual(JSON.parse(quoteJson({ amount: 50, active: true })), { total: 45 })
})
checkout/src/application/quote.mjs
import { memberPrice } from '../domain/price.mjs'
export const quote = (amount, active) => memberPrice(amount, active)
checkout/src/adapters/quote-json.mjs
import { quote } from '../application/quote.mjs'
export const quoteJson = ({ amount, active }) => JSON.stringify({ total: quote(amount, active) })
checkout/src/domain/price.mjs
export const memberPrice = (amount, active) => active ? amount * 0.9 : amount
